-- IF EXISTS skip notices are SQLSTATE 00000 with PostgreSQL's wording.
DROP USER MAPPING IF EXISTS FOR current_user SERVER nosuch;
DROP SERVER IF EXISTS nosuch;
DROP FOREIGN DATA WRAPPER IF EXISTS nosuch;
DROP ROLE IF EXISTS nosuch;
DROP EVENT TRIGGER IF EXISTS nosuch;
DROP COLLATION IF EXISTS nosuch;
DROP CONVERSION IF EXISTS nosuch;
CREATE TABLE skip_rules (a int);
DROP RULE IF EXISTS nosuch ON skip_rules;
CREATE TYPE skip_type AS (a int);
ALTER TYPE skip_type DROP ATTRIBUTE IF EXISTS nosuch;
DROP ACCESS METHOD IF EXISTS nosuch;
DROP TEXT SEARCH DICTIONARY IF EXISTS nosuch;
DROP TEXT SEARCH CONFIGURATION IF EXISTS nosuch;
CREATE FOREIGN DATA WRAPPER skip_wrapper;
CREATE SERVER skip_server FOREIGN DATA WRAPPER skip_wrapper;
DROP USER MAPPING IF EXISTS FOR current_user SERVER skip_server;
DROP USER MAPPING FOR current_user SERVER skip_server;
DROP USER MAPPING IF EXISTS FOR PUBLIC SERVER skip_server;
ALTER USER MAPPING FOR PUBLIC SERVER skip_server OPTIONS (ADD a 'b');
DROP SERVER skip_server;
DROP FOREIGN DATA WRAPPER skip_wrapper;
DROP TABLE skip_rules;
DROP TYPE skip_type;
CREATE TYPE skip_cast AS (a int);
DROP CAST IF EXISTS (int AS skip_cast);
DROP CAST (int AS skip_cast);
COMMENT ON CAST (int AS skip_cast) IS 'x';
DROP TYPE skip_cast;
